<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Reports</title><style>body{font:15px Arial;background:#f4f6fa;color:#172b43}.wrap{max-width:1200px;margin:30px auto;padding:0 15px}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.card{background:#fff;padding:20px;border-radius:12px;margin:14px 0}.label{color:#718096;font-size:13px}.value{font-size:23px;font-weight:bold;margin-top:10px}input,select{padding:10px;border:1px solid #ccd5df;border-radius:6px;margin:4px}button,a{background:#173d65;color:#fff;padding:10px 14px;border:0;border-radius:7px;text-decoration:none;cursor:pointer}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:11px;border-bottom:1px solid #eee}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:450px){.grid{grid-template-columns:1fr}}</style></head><body><main class="wrap"><h1>Business Reports</h1><p>@if(auth()->user()->hasPermission('reports.export'))<a href="{{ route('reports.export',request()->query()) }}">Export Sales CSV</a>@endif <a href="{{ route('cashbook.index') }}">Cashbook</a> <a href="{{ route('dashboard') }}">Dashboard</a> <a href="{{ route('expenses.index') }}">Expenses</a> <a href="{{ route('supplier-payments.index') }}">Supplier Payments</a></p><div class="card"><form method="GET"><label>From <input type="date" name="from" value="{{ $from }}"></label><label>To <input type="date" name="to" value="{{ $to }}"></label>@if(auth()->user()->hasRole('owner'))<select name="branch_id"><option value="">All branches</option>@foreach($branches as $b)<option value="{{ $b->id }}" @selected((string)$branchId===(string)$b->id)>{{ $b->name }}</option>@endforeach</select>@endif<button>Run Report</button></form></div><div class="grid"><div class="card"><div class="label">Completed Sales</div><div class="value">{{ $saleCount }}</div></div><div class="card"><div class="label">Gross Sales (PKR)</div><div class="value">{{ number_format($grossSales,2) }}</div></div><div class="card"><div class="label">Returned / Exchanged Value (PKR)</div><div class="value">{{ number_format($refunds,2) }}</div></div><div class="card"><div class="label">Expenses (PKR)</div><div class="value">{{ number_format($expenses,2) }}</div></div><div class="card"><div class="label">Gross Profit (estimated, PKR)</div><div class="value">{{ number_format($grossProfit,2) }}</div></div><div class="card"><div class="label">Net Profit (estimated, PKR)</div><div class="value">{{ number_format($netProfit,2) }}</div></div><div class="card"><div class="label">Cash In (PKR)</div><div class="value">{{ number_format($cashIn,2) }}</div></div><div class="card"><div class="label">Cash Out (PKR)</div><div class="value">{{ number_format($cashOut,2) }}</div></div></div><div class="card"><h2>Inventory Valuation</h2><p class="value">PKR {{ number_format($stockValue,2) }}</p><p class="label">Current on-hand quantity × current variant cost price.</p></div><div class="card"><h2>Low Stock</h2><table><tr><th>Branch</th><th>Product</th><th>SKU</th><th>On Hand</th><th>Reorder At</th></tr>@forelse($lowStock as $s)<tr><td>{{ $s->branch->name }}</td><td>{{ $s->productVariant->product->name }}</td><td>{{ $s->productVariant->sku }}</td><td>{{ $s->quantity }}</td><td>{{ $s->reorder_level }}</td></tr>@empty<tr><td colspan="5">No low-stock items.</td></tr>@endforelse</table></div><div class="card"><h2>Daily Sales</h2><table><tr><th>Date</th><th>Sales PKR</th></tr>@forelse($dailySales as $day)<tr><td>{{ $day->day }}</td><td>{{ number_format($day->total,2) }}</td></tr>@empty<tr><td colspan="2">No sales in selected period.</td></tr>@endforelse</table></div></main></body></html>